import urllib.request, re

tools = ['photocraft', 'vectorcraft', 'filmcraft', 'lightcraft', 'pdfcraft', 'effectcraft', 'designcraft']

for t in tools:
    url = f'https://raw.githubusercontent.com/storytold/{t}/main/README.md'
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    try:
        with urllib.request.urlopen(req) as resp:
            data = resp.read().decode('utf-8', errors='ignore')
            print(f'********************* {t.upper()} *********************')
            # Extract title / overview
            m_title = re.search(r'#\s+(.+)', data)
            if m_title:
                print('Title:', m_title.group(1))

            # Find keywords: inpaint, watermark, clone, healing, fill, remove, stamp, ai, brush
            kws = ['inpaint', 'watermark', 'clone', 'heal', 'fill', 'remove', 'stamp', 'content-aware', 'ai', 'mcp']
            found_kws = {}
            for kw in kws:
                matches = re.findall(rf'([^.\n]*?{kw}[^.\n]*)', data, re.IGNORECASE)
                if matches:
                    found_kws[kw] = [m.strip() for m in matches[:3]]

            print('Relevant Keywords found:', list(found_kws.keys()))
            for kw, snippets in found_kws.items():
                print(f'  [{kw}]:')
                for s in snippets:
                    print('    -', s[:120])
            print()
    except Exception as e:
        print(f'Error fetching {t}: {e}')
"

